"import os
import re

def find_missing_doxygen(directory):
    for root, _, files in os.walk(directory):
        for file in files:
            if not file.endswith('.hpp'): continue
            path = os.path.join(root, file)
            with open(path, 'r') as f:
                lines = f.readlines()

            in_public_protected = False
            for i, line in enumerate(lines):
                stripped = line.strip()
                if stripped in ('public:', 'protected:'):
                    in_public_protected = True
                    continue
                if stripped in ('private:',):
                    in_public_protected = False
                    continue

                # Check if it looks like a method declaration (has '(' and ')')
                if in_public_protected and '(' in stripped and ')' in stripped and not stripped.startswith('//') and not stripped.startswith('/*'):
                    # look above for doxygen
                    has_doxy = False
                    for j in range(i-1, max(-1, i-5), -1):
                        prev = lines[j].strip()
                        if prev.endswith('*/'):
                            has_doxy = True
                            break
                        if prev == '' or prev.startswith('//'):
                            continue
                        break

                    if not has_doxy:
                        print(f"{path}:{i+1}: {stripped}")

find_missing_doxygen('lib')
